pub fn map_children(node: Rc<Node>, transform: impl Fn(Rc<Node>) -> Rc<Node>) -> Rc<Node> {
    Rc::new(Node {
        name: node.name.clone(),
        span: node.span.clone(),
        ident_span: node.ident_span.clone(),
        children: {
            let mut __result = Vec::new();
            for child in node.children.clone().iter().cloned() {
                __result.push(transform(child.clone()));
            }
            __result
        },
        connective: node.connective.clone(),
        params: node.params.clone(),
        inferred: node.inferred.clone(),
        return_cardinality: node.return_cardinality.clone(),
        uses: node.uses.clone(),
        body: node.body.clone(),
        transport: node.transport.clone(),
        properties: node.properties.clone(),
        type_annotation: node.type_annotation.clone(),
        is_self_recursive: node.is_self_recursive.clone(),
        has_non_tail_self_call: node.has_non_tail_self_call.clone(),
        match_pattern: node.match_pattern.clone(),
        expr_data: node.expr_data.clone(),
    })
}

pub fn expr_has_self_call(texpr: Rc<Node>, fn_name: String) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*texpr.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                let f = expr_call_func(texpr.clone());
                if (f.clone() == fn_name.clone()) {
                    true
                } else {
                    {
                        let mut __found = false;
                        for child in texpr.children.clone().iter().cloned() {
                            if expr_has_self_call(child.clone(), fn_name.clone()) {
                                __found = true;
                                break;
                            }
                        }
                        __found
                    }
                }
            }
            _ => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_self_call(child.clone(), fn_name.clone()) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
        }
    })
}

pub fn expr_has_non_tail_self_call(texpr: Rc<Node>, fn_name: String, in_tail: bool) -> bool {
    stacker::maybe_grow(512 * 1024, 2 * 1024 * 1024, || {
        match (*texpr.expr_data.clone()).clone() {
            ExprData::ExprCall { .. } => {
                let f = expr_call_func(texpr.clone());
                if (f.clone() == fn_name.clone()) {
                    if (in_tail.clone() == false) {
                        true
                    } else {
                        {
                            let mut __found = false;
                            for child in texpr.children.clone().iter().cloned() {
                                if expr_has_non_tail_self_call(
                                    child.clone(),
                                    fn_name.clone(),
                                    false,
                                ) {
                                    __found = true;
                                    break;
                                }
                            }
                            __found
                        }
                    }
                } else {
                    {
                        let mut __found = false;
                        for child in texpr.children.clone().iter().cloned() {
                            if expr_has_non_tail_self_call(child.clone(), fn_name.clone(), false) {
                                __found = true;
                                break;
                            }
                        }
                        __found
                    }
                }
            }
            ExprData::ExprError { .. } => false,
            ExprData::ExprVar { .. } => false,
            ExprData::ExprLiteral { .. } => false,
            ExprData::ExprFieldAccess { .. } => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(child.clone(), fn_name.clone(), false) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
            ExprData::ExprMethodCall { .. } => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(child.clone(), fn_name.clone(), false) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
            ExprData::ExprIf => {
                let cond_bad = expr_has_non_tail_self_call(
                    if_condition(texpr.clone()),
                    fn_name.clone(),
                    false,
                );
                let then_bad = expr_has_non_tail_self_call(
                    if_then_branch(texpr.clone()),
                    fn_name.clone(),
                    in_tail.clone(),
                );
                let else_bad = match if_else_branch(texpr.clone()) {
                    Some(e) => {
                        expr_has_non_tail_self_call(e.clone(), fn_name.clone(), in_tail.clone())
                    }
                    None => false,
                };
                ((cond_bad.clone() || then_bad.clone()) || else_bad.clone())
            }
            ExprData::ExprMatch => {
                let scrut_bad = expr_has_non_tail_self_call(
                    match_scrutinee(texpr.clone()),
                    fn_name.clone(),
                    false,
                );
                let arms_bad = {
                    let mut __found = false;
                    for arm_node in match_arm_nodes(texpr.clone()).iter().cloned() {
                        if expr_has_non_tail_self_call(
                            arm_body(arm_node.clone()),
                            fn_name.clone(),
                            in_tail.clone(),
                        ) {
                            __found = true;
                            break;
                        }
                    }
                    __found
                };
                (scrut_bad.clone() || arms_bad.clone())
            }
            ExprData::ExprLet => {
                let val_bad =
                    expr_has_non_tail_self_call(let_value(texpr.clone()), fn_name.clone(), false);
                let body_bad = match let_body(texpr.clone()) {
                    Some(b) => {
                        expr_has_non_tail_self_call(b.clone(), fn_name.clone(), in_tail.clone())
                    }
                    None => false,
                };
                (val_bad.clone() || body_bad.clone())
            }
            ExprData::ExprBlock => {
                let ss = texpr.children.clone();
                let ss_count = (ss.clone().len() as i64);
                if (ss_count.clone() == 0) {
                    false
                } else {
                    {
                        let init_bad = {
                            let mut __found = false;
                            for p in {
                                let mut __result = Vec::new();
                                for p in ss
                                    .clone()
                                    .iter()
                                    .cloned()
                                    .enumerate()
                                    .map(|(i, v)| (i as i64, v))
                                    .collect::<Vec<_>>()
                                    .iter()
                                    .cloned()
                                {
                                    if (p.0.clone() < (ss_count.clone() - 1)) {
                                        __result.push(p);
                                    }
                                }
                                __result
                            }
                            .iter()
                            .cloned()
                            {
                                if expr_has_non_tail_self_call(p.1.clone(), fn_name.clone(), false)
                                {
                                    __found = true;
                                    break;
                                }
                            }
                            __found
                        };
                        let last_bad = match ss.clone().last().cloned() {
                            Some(last_expr) => expr_has_non_tail_self_call(
                                last_expr.clone(),
                                fn_name.clone(),
                                in_tail.clone(),
                            ),
                            None => false,
                        };
                        (init_bad.clone() || last_bad.clone())
                    }
                }
            }
            ExprData::NoExprData => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(child.clone(), fn_name.clone(), in_tail.clone())
                    {
                        __found = true;
                        break;
                    }
                }
                __found
            }
            _ => {
                let mut __found = false;
                for child in texpr.children.clone().iter().cloned() {
                    if expr_has_non_tail_self_call(child.clone(), fn_name.clone(), false) {
                        __found = true;
                        break;
                    }
                }
                __found
            }
        }
    })
}

