pub fn module_node(
    name: String,
    imports: Vec<Rc<Node>>,
    items: Vec<Rc<Node>>,
    span: Rc<SourceSpan>,
) -> Rc<Node> {
    {
        let marker = make_field_init_node(
            "__is_module".to_string(),
            make_expr_node(
                Rc::new(ExprData::ExprLiteral {
                    value: Rc::new(LiteralValue::LitStr {
                        value: "true".to_string(),
                    }),
                }),
                vec![],
                None,
                SourceSpan::new(0, 0),
            ),
            no_span(),
        );
        Rc::new(Node {
            name: name.clone(),
            span: span.clone(),
            ident_span: default_ident_span(name.clone(), span.clone()),
            children: v2_rt::concat(imports.clone(), items.clone()),
            connective: None,

            params: vec![],
            inferred: None,
            return_cardinality: Cardinality::Required,
            uses: vec![],
            body: None,
            transport: None,
            properties: vec![marker.clone()],
            type_annotation: None,
            is_self_recursive: false,
            has_non_tail_self_call: false,
            match_pattern: None,
            expr_data: Rc::new(ExprData::NoExprData),
        })
    }
}

pub fn import_node(
    module_path: String,
    is_all: bool,
    specific_names: Vec<Rc<Node>>,
    span: Rc<SourceSpan>,
) -> Rc<Node> {
    {
        let import_prop = make_field_init_node(
            "__is_import".to_string(),
            make_expr_node(
                Rc::new(ExprData::ExprLiteral {
                    value: Rc::new(LiteralValue::LitStr {
                        value: "true".to_string(),
                    }),
                }),
                vec![],
                None,
                SourceSpan::new(0, 0),
            ),
            no_span(),
        );
        let all_prop = if is_all.clone() {
            vec![make_field_init_node(
                "__import_all".to_string(),
                make_expr_node(
                    Rc::new(ExprData::ExprLiteral {
                        value: Rc::new(LiteralValue::LitStr {
                            value: "true".to_string(),
                        }),
                    }),
                    vec![],
                    None,
                    SourceSpan::new(0, 0),
                ),
                no_span(),
            )]
        } else {
            vec![]
        };
        Rc::new(Node {
            name: module_path.clone(),
            span: span.clone(),
            ident_span: default_ident_span(module_path.clone(), span.clone()),
            children: specific_names.clone(),
            connective: None,

            params: vec![],
            inferred: None,
            return_cardinality: Cardinality::Required,
            uses: vec![],
            body: None,
            transport: None,
            properties: v2_rt::concat(vec![import_prop.clone()], all_prop.clone()),
            type_annotation: None,
            is_self_recursive: false,
            has_non_tail_self_call: false,
            match_pattern: None,
            expr_data: Rc::new(ExprData::NoExprData),
        })
    }
}

