// =========================================================================
// NewlineIndex — byte-offset-to-line:col translation
// =========================================================================

#[derive(Debug, Clone, PartialEq)]
pub struct LineCol {
    pub line: i64,
    pub col: i64,
}

#[derive(Debug, Clone, PartialEq)]
pub struct NewlineIndex {
    pub file: String,
    pub offsets: Vec<i64>,
    pub source: String,
}

// Build newline index using CHARACTER offsets (matching the tokenizer).
// The tokenizer advances pos by 1 per character (via char_at), not per byte.
// Offsets in this index are character positions, not byte positions.
pub fn build_newline_index(file: String, source: String) -> Rc<NewlineIndex> {
    let mut offsets = Vec::new();
    for (i, ch) in source.chars().enumerate() {
        if ch == '\n' {
            offsets.push((i as i64) + 1);
        }
    }
    Rc::new(NewlineIndex {
        file,
        offsets,
        source,
    })
}

// Character offset → line:col. Both are 1-based.
// Offsets are character-indexed (matching tokenizer spans).
pub fn byte_to_line_col(index: Rc<NewlineIndex>, offset: i64) -> Rc<LineCol> {
    let offset_usize = offset.max(0) as usize;
    let pos = index
        .offsets
        .partition_point(|&o| (o as usize) <= offset_usize);
    let line = (pos as i64) + 1;
    let line_start = if pos == 0 {
        0i64
    } else {
        index.offsets[pos - 1]
    };
    let col = offset - line_start + 1;
    Rc::new(LineCol { line, col })
}

// Extract the text of a source line by character offsets.
pub fn source_line_at(index: Rc<NewlineIndex>, line: i64) -> String {
    if line < 1 {
        return String::new();
    }
    let line_idx = (line as usize) - 1;
    let char_start = if line_idx == 0 {
        0usize
    } else {
        match index.offsets.get(line_idx - 1) {
            Some(&o) => o as usize,
            None => return String::new(),
        }
    };
    let char_end = match index.offsets.get(line_idx) {
        Some(&o) => (o as usize).saturating_sub(1), // exclude the '\n'
        None => index.source.chars().count(),
    };
    if char_start > char_end {
        return String::new();
    }
    index
        .source
        .chars()
        .skip(char_start)
        .take(char_end - char_start)
        .collect()
}

// Extract source text by character-indexed span.
pub fn source_text_at(index: Rc<NewlineIndex>, span: Rc<SourceSpan>) -> String {
    let start = span.start.max(0) as usize;
    let end = span.end.max(span.start).max(0) as usize;
    if end <= start {
        return String::new();
    }
    index.source.chars().skip(start).take(end - start).collect()
}

pub fn node_is_product(n: Rc<Node>) -> bool {
    ((n.connective.clone() != None) && (n.connective.clone() == Some(Connective::Conj)))
}

pub fn node_is_coproduct(n: Rc<Node>) -> bool {
    ((n.connective.clone() != None) && (n.connective.clone() == Some(Connective::Disj)))
}

pub fn node_has_structure(n: Rc<Node>) -> bool {
    (node_is_product(n.clone()) || node_is_coproduct(n.clone()))
}
